// The only place the interface talks to the engine.
//
// Every call goes through here, typed against the bindings generated from the shell's wire
// types (`src/lib/bindings/`, regenerated by `npm run bindings`). Nothing else in the
// interface imports `invoke`, so the whole surface is one file to read.

import { invoke } from "@tauri-apps/api/core";

import type { Appraisal } from "./bindings/Appraisal";
import type { CitationRequest } from "./bindings/CitationRequest";
import type { Contributor } from "./bindings/Contributor";
import type { Document } from "./bindings/Document";
import type { DocumentRef } from "./bindings/DocumentRef";
import type { EngineError } from "./bindings/EngineError";
import type { Field } from "./bindings/Field";
import type { Form } from "./bindings/Form";
import type { LibraryFolder } from "./bindings/LibraryFolder";
import type { LibraryStatus } from "./bindings/LibraryStatus";
import type { Locator } from "./bindings/Locator";
import type { RecentLibrary } from "./bindings/RecentLibrary";
import type { RenamedLibrary } from "./bindings/RenamedLibrary";
import type { Role } from "./bindings/Role";
import type { Keep } from "./bindings/Keep";
import type { SavedSource } from "./bindings/SavedSource";
import type { SearchHit } from "./bindings/SearchHit";
import type { Source } from "./bindings/Source";
import type { Split } from "./bindings/Split";
import type { SourceDate } from "./bindings/SourceDate";
import type { SourceType } from "./bindings/SourceType";
import type { Topic } from "./bindings/Topic";
import type { TopicContents } from "./bindings/TopicContents";
import type { Contents } from "./bindings/Contents";

export type {
  Appraisal,
  CitationRequest,
  Contributor,
  Document,
  DocumentRef,
  EngineError,
  Field,
  Form,
  Keep,
  LibraryFolder,
  LibraryStatus,
  Locator,
  RecentLibrary,
  RenamedLibrary,
  Role,
  SavedSource,
  SearchHit,
  Source,
  SourceDate,
  SourceType,
  Split,
  Topic,
  TopicContents,
  Contents,
};

/** The opaque token carried between a read and a write. Never inspected. */
export type Revision = Document["revision"];

/** The error causes from `backend-contract.md`. */
export type ErrorKind = EngineError["kind"];

/** A failure the interface can branch on, rather than a string to show raw. */
export class EngineFailure extends Error {
  readonly kind: ErrorKind;

  constructor(error: EngineError) {
    super(error.message);
    this.name = "EngineFailure";
    this.kind = error.kind;
  }
}

function looksLikeEngineError(value: unknown): value is EngineError {
  return (
    typeof value === "object" &&
    value !== null &&
    "kind" in value &&
    "message" in value &&
    typeof (value as EngineError).kind === "string"
  );
}

/**
 * Is the desktop runtime present?
 *
 * Every call below needs it. Opening the Vite dev server in an ordinary browser gives you the
 * page but no engine and no native dialogs, so the interface must say so rather than looking
 * broken — which is exactly how it looks when a button does nothing.
 */
export function isDesktopRuntime(): boolean {
  return typeof window !== "undefined" && "__TAURI_INTERNALS__" in window;
}

async function call<T>(command: string, args?: Record<string, unknown>): Promise<T> {
  try {
    return await invoke<T>(command, args);
  } catch (thrown) {
    // The shell returns a structured failure; anything else is a bug in the bridge and is
    // reported as such rather than being flattened into the same shape.
    if (looksLikeEngineError(thrown)) throw new EngineFailure(thrown);
    throw new EngineFailure({
      kind: "LibraryError",
      message: `unexpected failure from ${command}: ${String(thrown)}`,
    });
  }
}

export const engine = {
  library: {
    /** A new library, in a folder of its own named after it, inside `location`. */
    create: (location: string, name: string) =>
      call<LibraryStatus>("library_create", { location, name }),
    open: (path: string) => call<LibraryStatus>("library_open", { path }),
    close: () => call<void>("library_close"),
    status: () => call<LibraryStatus>("library_status"),
    rebuildIndex: () => call<LibraryStatus>("library_rebuild_index"),
    /**
     * A new name for the open library, and for its folder too while the folder is the
     * library's alone. The answer says which, and carries the folder's new path if it moved.
     */
    rename: (name: string) => call<RenamedLibrary>("library_rename", { name }),
  },
  topic: {
    tree: () => call<Topic[]>("topic_tree"),
    create: (parent: string | null, name: string) =>
      call<string>("topic_create", { parent, name }),
    rename: (topic: string, name: string) =>
      call<void>("topic_rename", { topic, name }),
    /**
     * What deleting this topic would reach: every document anywhere below it, by name.
     *
     * Always asked before `delete`, never after — the person is shown this first.
     */
    deletePlan: (topic: string) => call<TopicContents>("topic_delete_plan", { topic }),
    /**
     * Delete a topic, having been told what becomes of what is inside.
     *
     * There is no default for `contents`. The contract has said since M0 that deleting a
     * topic never deletes documents implicitly, and a default would be exactly that.
     */
    delete: (topic: string, contents: Contents) =>
      call<void>("topic_delete", { topic, contents }),
  },
  document: {
    create: (topic: string, title: string) =>
      call<string>("document_create", { topic, title }),
    read: (document: string) => call<Document>("document_read", { document }),
    write: (document: string, body: string, revision: Revision) =>
      call<Document>("document_write", { document, body, revision }),
    rename: (document: string, title: string) =>
      call<Document>("document_rename", { document, title }),
    delete: (document: string) => call<void>("document_delete", { document }),
    /**
     * Keep a picture with this document, and get back the name to write into the body.
     *
     * The library takes its own copy either way, so the file the user picked may be gone
     * afterwards. The name is the engine's, made unique against everything already beside
     * the document — never the name of the file that was picked.
     */
    attachImage: (document: string, path: string, keep: Keep) =>
      call<string>("document_attach_image", { document, path, keep }),
    /**
     * A picture this document's body names, as a `data:` URL to put straight into an `img`.
     *
     * A **document** and a **name from its own body** are named here, never a path — so
     * nothing the interface can say reaches a file the engine did not resolve. `null` means
     * there is nothing to show: the file has been deleted, or the name never led anywhere.
     * Not an error — a user may do what they like inside their own library.
     */
    image: (document: string, name: string) =>
      call<string | null>("document_image", { document, name }),
    /**
     * The documents linking here.
     *
     * Derived from the `[[…]]` in other documents rather than stored anywhere, so it cannot
     * go out of step with the writing: a link deleted in a text editor stops being a
     * backlink the next time the library is read.
     */
    backlinks: (document: string) =>
      call<DocumentRef[]>("document_backlinks", { document }),
    /**
     * Take part of a document out into a new one, leaving a link behind.
     *
     * `start` and `end` are **character offsets into the body last read**, not editor
     * positions — see `offsetOf` in `body.ts` for why those are different things. The
     * revision comes with them because offsets into a file that changed underneath address
     * different text, and splitting on them takes the wrong words out of a document.
     */
    split: (
      document: string,
      start: number,
      end: number,
      title: string,
      revision: Revision,
    ) => call<Split>("document_split", { document, start, end, title, revision }),
  },
  source: {
    create: (source: Source) => call<SavedSource>("source_create", { source }),
    read: (source: string) => call<Source>("source_read", { source }),
    /** Returns whatever required fields the saved source still lacks — not an error. */
    update: (source: Source) => call<Field[]>("source_update", { source }),
    list: () => call<Source[]>("source_list"),
    /** What deleting this source would orphan. Ask before `delete`, never after. */
    deletePlan: (source: string) =>
      call<DocumentRef[]>("source_delete_plan", { source }),
    delete: (source: string) => call<void>("source_delete", { source }),
    citingDocuments: (source: string) =>
      call<DocumentRef[]>("source_citing_documents", { source }),
    /**
     * Keep a copy of a PDF with this source.
     *
     * The library takes its own copy either way, so the original can be gone afterwards and
     * the source still has its paper. `keep` decides what becomes of the file the user
     * picked: left alone, or taken away once the copy is safe.
     */
    attach: (source: string, path: string, keep: Keep) =>
      call<Source>("source_attach", { source, path, keep }),
    /** Forget the paper, and delete the library's copy of it. */
    detach: (source: string) => call<Source>("source_detach", { source }),
    /**
     * Open the kept PDF in whatever the desktop uses for PDFs.
     *
     * A **source** is named here, never a path — the path is the engine's answer, which is
     * why the interface needs no filesystem permission of its own. `false` means there was
     * nothing to open, which is not an error: a user may delete files from their own library.
     */
    open: (source: string) => call<boolean>("source_open", { source }),
    requiredFields: (sourceType: SourceType) =>
      call<Field[]>("source_required_fields", { sourceType }),
  },
  citation: {
    format: (source: string, form: Form, locator: Locator | null = null) =>
      call<string>("citation_format", { source, form, locator }),
    /**
     * Render many at once — what the editor uses to draw a document.
     *
     * `null` in a slot means that source no longer exists. One citation pointing nowhere must
     * not blank the other fourteen, so the hole is reported rather than the batch failing.
     */
    formatMany: (requests: CitationRequest[]) =>
      call<(string | null)[]>("citation_format_many", { requests }),
    referenceList: (document: string) =>
      call<string[]>("citation_reference_list", { document }),
  },
  search: (query: string) => call<SearchHit[]>("search", { query }),
};

/**
 * What the shell keeps for itself between runs: the libraries this computer has opened.
 *
 * Not the engine, and not in any library. The list lives in the application's settings folder
 * and is a convenience only — losing it costs a folder dialog — so it is no part of the engine
 * contract, and opening a library is what adds one to it.
 */
export const shell = {
  /** Most recent first, including any whose folder cannot be found just now. */
  recentLibraries: () => call<RecentLibrary[]>("recent_libraries"),
  /** Take a library off the list. The library itself is not touched. */
  forgetLibrary: (path: string) => call<void>("forget_library", { path }),
};
